import Cocoa
import ApplicationServices

func axValue(_ element: AXUIElement, _ attr: CFString) -> AnyObject? {
    var value: CFTypeRef?
    let err = AXUIElementCopyAttributeValue(element, attr, &value)
    return err == .success ? (value as AnyObject?) : nil
}

func children(of element: AXUIElement) -> [AXUIElement] {
    (axValue(element, kAXChildrenAttribute) as? [AXUIElement]) ?? []
}

func title(of element: AXUIElement) -> String? {
    (axValue(element, kAXTitleAttribute) as? String) ?? (axValue(element, kAXDescriptionAttribute) as? String)
}

func role(of element: AXUIElement) -> String? { axValue(element, kAXRoleAttribute) as? String }

func press(_ element: AXUIElement) -> Bool {
    return AXUIElementPerformAction(element, kAXPressAction) == .success
}

func search(_ element: AXUIElement, match: (AXUIElement)->Bool, depth: Int = 0) -> AXUIElement? {
    if match(element) { return element }
    if depth > 20 { return nil }
    for child in children(of: element) {
        if let found = search(child, match: match, depth: depth + 1) { return found }
    }
    return nil
}

let system = AXUIElementCreateSystemWide()
var focusedAppRef: CFTypeRef?
AXUIElementCopyAttributeValue(system, kAXFocusedApplicationAttribute as CFString, &focusedAppRef)
let app = (focusedAppRef.map { unsafeBitCast($0, to: AXUIElement.self) }) ?? AXUIElementCreateApplication(0)

// Find the alert button first.
if let later = search(app, match: { el in title(of: el) == "Later" }) {
    _ = press(later)
}

sleep(1)

// Refresh app ref in case alert changed focus.
focusedAppRef = nil
AXUIElementCopyAttributeValue(system, kAXFocusedApplicationAttribute as CFString, &focusedAppRef)
let app2 = (focusedAppRef.map { unsafeBitCast($0, to: AXUIElement.self) }) ?? AXUIElementCreateApplication(0)

if let team = search(app2, match: { el in title(of: el) == "Team Standup" }) {
    _ = press(team)
}

sleep(1)

focusedAppRef = nil
AXUIElementCopyAttributeValue(system, kAXFocusedApplicationAttribute as CFString, &focusedAppRef)
let app3 = (focusedAppRef.map { unsafeBitCast($0, to: AXUIElement.self) }) ?? AXUIElementCreateApplication(0)

if let header = search(app3, match: { el in
    guard let t = title(of: el) else { return false }
    return t == "Team Standup" && (role(of: el) == kAXButtonRole as String || role(of: el) == kAXStaticTextRole as String)
}) {
    _ = press(header)
}
